INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Политические партии: правовой статус','Партия создала региональные отделения ровно в половине субъектов Российской Федерации. Соблюдено ли территориальное условие статьи 3?','["Нет, необходимо строго более половины","Нет, отделения нужны в каждом субъекте","Да, требуется не менее половины субъектов","Да, но только при дополнительном одобрении Совета Федерации"]'::jsonb,2,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','У политической партии 499 членов при выполнении остальных требований закона. Какая недостающая характеристика препятствует соблюдению статьи 3?','["Необходимо минимум 1000 членов партии","Необходимо минимум 500 членов партии","Необходимо минимум 500 членов в каждом отделении","Требуется не менее 750 членов партии"]'::jsonb,1,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','В одном субъекте решили образовать два региональных отделения одной политической партии. Какова правовая оценка?','["Допускается только одно региональное отделение этой партии в субъекте","Допускается два, если второе отделение не участвует в выборах","Допускается любое число по региональному уставу","Допускается только после решения Центральной избирательной комиссии"]'::jsonb,0,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','Региональные отделения партии созданы в нескольких субъектах, но руководящий орган постоянно расположен за рубежом. Какое требование не выполнено?','["Все органы партии обязательно должны располагаться в Москве","За рубежом запрещены только региональные отделения","Требование места нахождения касается лишь избирательных комиссий","Руководящие и иные органы партии должны находиться в Российской Федерации"]'::jsonb,3,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','Объединение зарегистрировано как общественная организация и планирует выдвигать кандидатов на выборах. Какое понимание партии закреплено статьёй 3?','["Любая общественная организация автоматически становится партией","Политическая партия является государственным органом","Политическая партия — вид общественной организации с целями политического участия","Партия — только коммерческая форма организации"]'::jsonb,2,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','В партии решают установить минимальное число участников отдельно для региональных отделений. Допускает ли это закон?','["Нет, минимальный размер каждого отделения всегда прямо фиксирован федеральным законом","Да, такие требования могут предусматриваться уставом партии","Да, но только постановлением регионального парламента","Нет, устав вообще не может определять состав отделений"]'::jsonb,1,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','Партия хочет закрепить политические цели исключительно во внутреннем приказе руководителя, не отражая их в основных документах. Что предусматривает статья 3?','["Цели и задачи должны быть изложены в уставе и программе","Достаточно любого приказа без устава и программы","Цели определяются только Центральной избирательной комиссией","Цели политической партии законом не регулируются"]'::jsonb,0,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','Уполномоченный орган партии создал подразделение, действующее на территории субъекта РФ. Какой статус это подразделение имеет при соблюдении закона?','["Федеральный орган государственной власти","Территориальная избирательная комиссия","Самостоятельный субъект Российской Федерации","Региональное отделение политической партии"]'::jsonb,3,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','Устав партии предусматривает местные и первичные отделения. Как определяется порядок их создания по статье 3?','["Исключительно по отдельному федеральному закону для каждого отделения","Только постановлением Правительства РФ","В случаях и порядке, предусмотренных уставом партии","По решению губернатора независимо от устава"]'::jsonb,2,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true),
('Политические партии: правовой статус','Федеральный список партии получил право на распределение мест в Государственной Думе. Как квалифицируется партия по статье 3?','["Партия, имеющая только представительство в муниципальном собрании","Партия, представленная в Государственной Думе","Партия, представительство которой определяется исключительно числом её членов","Партия, автоматически сформировавшая Правительство РФ"]'::jsonb,1,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 Федерального закона № 95-ФЗ определяет требования к политической партии, её структуре и целям.',true)
